-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 notable NPCs are in' AS assertion, count(*) AS got, 4 AS want
  FROM notable_npcs WHERE slug IN ('max-the-undead-slayer', 'sergeant-beta', 'skippy', 'white-raven');
SELECT 'and the notables 11' AS assertion, count(*) AS got, 11 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('max-the-undead-slayer', 'sergeant-beta', 'skippy', 'white-raven');

