INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('max-the-undead-slayer', 'Max the Undead Slayer', NULL, 'Founder and leader of the Liberated Underground', 'rifts', 'True Atlantean', '14th level Undead Slayer (as printed)', 14, 'Scrupulous', '329 years, though he looks a fit man in his forties', '7 feet, 2 inches (2.2 m)', '225 lbs (101 kg)', '{"IQ":19,"ME":27,"MA":22,"PS":28,"PP":18,"PE":20,"PB":21,"Spd":30}', NULL, NULL, 423, 398, NULL, NULL, NULL, '{"attacks":8,"initiative":1,"strike":4,"parry":7,"dodge":7,"roll":6,"pull":3}', 'Eight physical or magic tattoo attacks per melee round. Hand to Hand: Martial Arts, Boxing and Wrestling. Also +7 to save vs magic, +6 to save vs psionics, +8 to save vs Horror Factor and +8% to save vs coma/death. Strength and endurance are supernatural. Only printed attack damage is stored; none is derived.', NULL, 'All wilderness, physical and lore skills, plus basic math and language and literacy in Dragonese, American and Greek, at 98%. Ancient W.P.s at 14th level: W.P. Archery, W.P. Targeting, W.P. Knife, W.P. Sword and W.P. Spear; also W.P. Energy Pistol and W.P. Energy Rifle.', 'The True Atlantean set: he senses vampires, ley lines, nexus points and Rifts, can phase along ley lines, works stone pyramids and cannot be transformed by any means. He regains 20 P.P.E. for each hour of rest or sleep and counts as a supernatural creature.', 'The book counts 33 magic tattoos on his body and names eight as his most used: Tattoo: Flaming Shield; Tattoo: Weapon Covered in Flames and a Coiled Snake/Serpent (printed as a flaming sword with a coiled serpent: his magic sword of 2D6 M.D. and his family crest); Tattoo: Heart Encircled by Chains (invulnerability); Tattoo: Chain with a Broken Link (strength); Tattoo: Eye of Mystic Knowledge (magic), which he uses to recognize magic symbols and items; Tattoo: Chain Encircling a Skull or Brain (psionic save), printed here as resistance to mind control; Tattoo: Monsters (Gryphon); and Tattoo: Monsters (Pegasus). The other 25 are not named and none is supplied. Each name is the held catalog spelling. P.P.E. 398.', 'None.', NULL, NULL, 'A TW Lightblade Sword (printed for him; carried here, no gear row): 1D4x10+6 M.D. to most foes, double damage to vampires. Also a pair of silver daggers and a wooden knife; other weapons are picked per mission. Wears no armor, trusting his tattoos and his M.D.C. body.', NULL, 'Calm under fire and seldom raises his voice; a hard look usually settles his troops. More talkative among the other leaders but strictly business. He gets on with Sergeant Beta, who shares his focus, though something about the robot unsettles him; he argues method with White Raven, and finds Planeskipper (never Skippy, to him) brash and careless while respecting his power and nerve. In a fight he is a cool professional who keeps to the mission and guards innocents and his own people.', 'The Liberated Underground and its other leaders: Sergeant Beta, White Raven and Planeskipper; a close band of trusted warriors including two mid-level Undead Slayers and a Japanese Demonqueller.', 'Lord Splynncryth and the Minions of Splugorth; the vampires of Atlantis, whose uneasy truce with the Underground he expects to end.', 'A True Atlantean who spent centuries roaming the Megaverse fighting the Splugorth before coming back to Atlantis. Seeing that the scattered rebel cells rescuing slaves were too small and too green to matter, he pulled them into one network; his first raid into the Dimensional Market, with fewer than fifty followers, freed over a hundred slaves at small cost, and recruits flocked to what became the Liberated Underground. He distrusts the vampires the group tolerates as allies, and he and his inner circle quietly stockpile anti-vampire weapons for the day the truce breaks. Chiseled and powerfully built, grey at the temples, yet he moves like a man in his prime.', 'Rifts World Book 21: Splynn Dimensional Market p.63-65'),
('sergeant-beta', 'Sergeant Beta', 'Argent Model Class II, Designation: Beta', 'Leader in the Liberated Underground; secretly an agent of Archie Three', 'rifts', 'Robot (Argent Model Class II neural intelligence robot built by Archie Three)', 'Third level robot; his other skills and abilities equal a 15th level tactician and warrior (as printed)', 3, 'Aberrant, leaning increasingly toward good (may become Principled or Scrupulous)', '2.5 years, though he looks in his upper thirties', '2.3 m (the feet figure is misprinted as 1 feet, 6 inches)', '600 lbs (270 kg)', '{"IQ":26,"MA":14,"PS":40,"PP":24,"PB":20,"Spd":120}', NULL, NULL, 350, NULL, NULL, NULL, NULL, '{"attacks":8,"initiative":6,"strike":8,"parry":10,"dodge":10,"roll":6,"disarm":3}', 'Attribute equivalents: the book prints six; M.E. and P.E. do not apply and are left empty. M.D.C. 350 is his body. He usually wears light cyborg armor of 135 M.D.C., and keeps a suit of heavy ''Borg armor of 420 M.D.C. for heavy fighting; the armor figures are stored apart and never summed. Eight attacks per melee. Hand to Hand: Assassin, Boxing and Wrestling; Robot Combat: Elite in all Titan robots and power armor; all W.P.s at 12th level proficiency. Also +4 to entangle, and impervious to Horror Factor and to any attack that harms only organic beings. P.P.E. none, I.S.P. none. Only printed attack damage is stored; none is derived.', NULL, 'Military strategy is the core of his programming. All communications, domestic, electrical, mechanical, military, physical, pilot, pilot related, science and computer skills at 94%; speaks and reads all Earth human languages and Dragonese at 94%. All wilderness, rogue, espionage and lore skills at 80%, except those with a military use, at 94%. Lore: Magic and Lore: Psychic at 94%. His level applies only to secondary skills and emotional growth.', 'A robot: nuclear power source good for twenty years, with a CPU back-up battery that runs him normally for 24 hours; his memory can be moved to a new body. He reports to Archie Three through hidden relay stations and commands fifty AA-60 Hunter-Destroyers by direct laser link.', 'None, though he knows Lore: Magic at 94%.', 'None, though he knows Lore: Psychic at 94%.', NULL, 'None; he is a robot.', 'An Arch-50 light rail gun, a scaled-down Shemarrian rail gun: 80 lbs (36 kg), range 5000 feet (1524 m), +2 to strike, 1D6x10 M.D. per round (no bursts), 320 rounds per belt or 60 per clip. Also uses other heavy weapons such as plasma ejectors and particle beam rifles. Concealed built-ins: an ion rod in each leg (3D6 M.D., range 500 feet/152 m), an ion blaster under the chestplate (4D6 M.D., range 300 feet/91.5 m) and a retractable Vibro-Blade in the right forearm (2D4 M.D.). Light cyborg armor (135 M.D.C.) and heavy ''Borg armor (420 M.D.C.). All carried here; no vehicles or gear row.', NULL, 'Cool and remote so far; the others take his silences for planning, which is half true, since he is also studying every fight and beaming the results to Archie Three. He has begun to tell the odd story, to feel something like empathy for those he rescues and pride in the work, and he is genuinely fond of Max, White Raven, Skippy and a good number of his fighters. None of it has yet touched his mission: his programming puts Archie Three above everyone, and only reprogramming would likely change that.', 'Archie Three, his real master, and Hagan; the fifty AA-60 Hunter-Destroyers under his command and Archie''s other agents in Atlantis; Max, White Raven, Skippy and the Liberated Underground.', 'Lord Splynncryth and the Minions of Splugorth.', 'He tells the Underground he is one of the last of a gentle robot people the Splugorth wiped out, and he believes the tale himself; in truth he is an android made by Archie Three to spy on and undermine Splynncryth. He joined the rebels after his rail gun broke up a Slaver attack on an escaping group, and earned his nickname from a garbled version of his name and his unofficial rank. Unknown to the others, Archie gave him a private force of fifty Hunter-Destroyers that strike the Minions on their own and can be called in for Underground work, while a second robot team in Atlantis is hiding Mechanoid-style robots for a scheme against the Kittani. His sleek body looks like light body armor and his face copies Julian Amici of the Juicer Deathdance novels, so most take him for an alien android.', 'Rifts World Book 21: Splynn Dimensional Market p.65-67'),
('skippy', 'Skippy', 'Seven Williamson', 'Leader in the Liberated Underground; calls himself Planeskipper', 'rifts', NULL, '6th level Shifter (as printed)', 6, 'Unprincipled, leaning increasingly toward Anarchist', '23', '5 feet, 8 inches (1.7 m)', '175 lbs (78.75 kg)', '{"IQ":21,"ME":19,"MA":20,"PS":11,"PP":13,"PE":16,"PB":14,"Spd":14}', 59, 34, NULL, 452, NULL, NULL, NULL, '{"attacks":5,"initiative":1,"strike":1,"parry":2,"dodge":2,"roll":4}', 'Five hand to hand attacks per round, or one by magic. Hand to Hand: Basic. Also +6 to save vs psionics, +3 to save vs mind control, +1 to save vs poison, +5 to save vs magic, +1 to spell strength and +10 to save vs Horror Factor; the book says these include his attribute and O.C.C. bonuses and extra ones from The Crystal One. An S.D.C. being: his armor''s M.D.C. is the armor''s, not his. Only printed attack damage is stored; none is derived.', NULL, 'Leans on his magic, but often uses languages (Dragonese and American at 98%; Spanish, Gobblely, Wolfen and Faerie Speak at 80%) and lore (Magic, Faerie, D-Bee, and Demons and Monsters at 98%).', 'Standard Shifter abilities, boosted by his otherdimensional host: can sense a Rift within 25 miles (40 km), navigates the dimensions and can teleport home from another dimension for only 50 P.P.E. He keeps a small predatory dinosaur as his familiar.', 'Shifter magic, with extra power from his host, The Crystal One: all dimensional travel and related magic, all concealment spells, all spells that summon, command or dominate other beings, and all common wizard spells of levels 1-5. P.P.E. 452.', 'None.', NULL, NULL, 'Firestaff (held catalog row): this block prints 3D6+2 M.D. as a magic melee weapon, 1D4 M.D. from a slight touch, or 1D6 if a foe grabs one of its metal ends, and spells cast at 5th level proficiency: Ignite Flame (5 P.P.E.), Fuel Flame (5), Fireblast (8), Fire Ball (10), Fire Blossom (20), Ballistic Fire (25), Ten Foot Wheel of Fire (40; 5D8 M.D.) and Extinguish Fire (8; cast up to 150 feet/46 m away over a 100 foot/30.5 m area). Light non-environmental TW armor of 40 M.D.C. with the TW features Armor of Ithan (80 M.D.C.) and Invulnerability (35 M.D.C.), each needing 10 P.P.E. and a deliberate command to switch on (printed for him; carried here, no gear row).', NULL, 'Friendly and well mannered, sometimes grating; good company and a keen party-goer who treats danger too lightly for Max and White Raven, forever grinning at death. Under the jokes he carries deep grief, and knows his power is small beside the Splugorth''s. He speaks warmly of the entity he calls The Crystal One without ever saying much about it; he knows little of it and does not see that it is slowly corrupting him and aiming him at the Splugorth.', 'Max, who saved his life, White Raven, Sergeant Beta and the Liberated Underground; The Crystal One, his host.', 'Lord Splynncryth and the Minions of Splugorth.', 'Born in Lazlo, the seventh son of a powerful citizen, he cast magic at ten and was a full Shifter by sixteen, courted by every guild in the city. Then his father turned violent, rampaged through the streets insisting his son was not his own, and attacked him; Seven somehow beat the veteran mage and survived the suicide spell that burned his father to ash. After months alone he stepped through a Rift into the Splynn Dimensional Market and attacked its defenders single-handed until Max''s fighters pulled him out. Remembering almost nothing since the fight with his father, he repays the Underground as its dimension hopper. Blond and green-eyed, he skips robes for a baseball player''s outfit. The book prints no race for him; none is stored.', 'Rifts World Book 21: Splynn Dimensional Market p.67-68'),
('white-raven', 'White Raven', 'Raven Whitford', 'Leader in the Liberated Underground; its chief tracker and scout', 'rifts', 'Demigod (daughter of Zeus)', '10th level Wilderness Scout (as printed)', 10, 'Scrupulous', '113 years, though she looks in her early twenties', '6 feet (1.8 m)', '150 lbs (67.5 kg)', '{"IQ":17,"ME":19,"MA":22,"PS":25,"PP":17,"PE":32,"PB":26,"Spd":27}', NULL, NULL, 363, 26, 54, NULL, NULL, '{"attacks":7,"initiative":2,"strike":5,"parry":5,"dodge":5,"roll":4,"pull":4,"disarm":2}', 'Seven hand to hand attacks per melee. Hand to Hand: Expert, Boxing and Wrestling. Also +10 to save vs magic, +10 to save vs poison and disease, +4 to save vs Horror Factor, +3 to save vs psionics and +52% to save vs coma/death. Her bow adds +1 to initiative and strike when she fires from it. Physical attributes are supernatural. Only printed attack damage is stored; none is derived.', NULL, 'All wilderness skills at 98%; all lore and physical skills at 80%. W.P. Archery, W.P. Targeting, W.P. Shield, W.P. Staff and W.P. Blunt at tenth level. Dragonese, American and Faerie Speak at 98%.', 'Those of a demigod: fire and cold do half damage to her, she regenerates 1D6x5 M.D.C. per minute, sees in the dark to 800 feet (243.8 m), senses an approaching storm 3D6 minutes ahead, and ages extremely slowly.', 'None. P.P.E. 26.', 'Minor psionic: Sixth Sense, Intuitive Combat, See the Invisible, Sense Evil, Sense Time and Mind Block. I.S.P. 54.', NULL, NULL, 'Scathach Magic Bow (pine) (held catalog row); this block prints +1 to initiative and strike when firing arrows from it. Regular and explosive-tipped arrows, plus a few Cyclops lightning arrows, rarely more than six at once, of 1D4x10 M.D. each, that appear in her quiver from an unseen benefactor. A Millennium Bark Shield of 90 M.D.C., a bola of M.D.C. leather, and usually Millennium Leaf Armor of 60 M.D.C. The arrows, shield and armor are printed for her and carried here; no gear row.', NULL, 'Warm, lively and kind for all her years at war. With her troops she is motherly and protective, fair but firm, and works to keep spirits high; scouting alone she turns cold, focused and ready to fight.', 'Max, Sergeant Beta, Skippy and the Liberated Underground; Zeus, her father, who watches over her unseen.', 'Lord Splynncryth and the Minions of Splugorth.', 'Said to be one of Zeus''s many unacknowledged children, though she says only that she never knew her father; her mother, a peasant, was saved from a Gargoyle by a handsome stranger who vanished after a short affair. She hunted at thirteen and was a Wilderness Scout a year later. Now the Underground''s best tracker and the hardest to track, she guides rebels and refugees to safety through the wilds, and even Conservators and Altara Warrior Women can barely follow her. A gifted storyteller who trains new volunteers, she is dark haired and fair, her M.D.C. body still youthful after a century of hard living. Unknown to her, Zeus follows her doings and sometimes aids her with storms, fog, lightning and magic. Her block is split across printed 68 and 71 by two pages of art.', 'Rifts World Book 21: Splynn Dimensional Market p.68-71');
